#!/usr/bin/env bash
# Read-only preflight for the HA environment generated by install-ha.sh.
#
#   ./verify-ha.sh deploy/provision-ha.env
#
# Exit codes: 0 = passed, 2 = passed with warnings, 1 = failed.
set -uo pipefail

ENV_FILE=${1:-deploy/provision-ha.env}
if [ ! -f "$ENV_FILE" ]; then
  echo "error: environment file not found: $ENV_FILE" >&2
  exit 1
fi

# shellcheck disable=SC1090
source "$ENV_FILE"

fails=0
warns=0
ok()   { printf '  ok    %s\n' "$*"; }
info() { printf '  info  %s\n' "$*"; }
warn() { printf '  warn  %s\n' "$*"; warns=$((warns + 1)); }
fail() { printf '  FAIL  %s\n' "$*"; fails=$((fails + 1)); }

valid_ip() {
  local ip=$1 a b c d
  [[ $ip =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
  IFS=. read -r a b c d <<<"$ip"
  for n in "$a" "$b" "$c" "$d"; do
    [ "$n" -ge 0 ] 2>/dev/null && [ "$n" -le 255 ] 2>/dev/null || return 1
  done
}

valid_cidr() {
  local addr bits
  addr=${1%/*}
  bits=${1#*/}
  [ "$addr" != "$1" ] || return 1
  valid_ip "$addr" || return 1
  [[ $bits =~ ^[0-9]+$ ]] && [ "$bits" -ge 0 ] && [ "$bits" -le 32 ]
}

valid_port() {
  [[ $1 =~ ^[0-9]+$ ]] && [ "$1" -ge 1 ] && [ "$1" -le 65535 ]
}

ip_in_cidr() {
  local ip=$1 cidr=$2 base bits a b c d ip_int base_int mask
  base=${cidr%/*}
  bits=${cidr#*/}
  valid_ip "$ip" && valid_cidr "$cidr" || return 1
  IFS=. read -r a b c d <<<"$ip"
  ip_int=$(( (a << 24) + (b << 16) + (c << 8) + d ))
  IFS=. read -r a b c d <<<"$base"
  base_int=$(( (a << 24) + (b << 16) + (c << 8) + d ))
  if [ "$bits" -eq 0 ]; then return 0; fi
  mask=$(( (0xFFFFFFFF << (32 - bits)) & 0xFFFFFFFF ))
  [ $(( ip_int & mask )) -eq $(( base_int & mask )) ]
}

echo "HA preflight: $ENV_FILE"
echo "========================"

# ---------------------------------------------------------------------------
# Build host
# ---------------------------------------------------------------------------
echo
echo "Build host"

for tool in git go helm podman ssh; do
  if command -v "$tool" >/dev/null 2>&1; then
    ok "$tool is installed"
  else
    fail "$tool is missing on the machine running provision.sh"
  fi
done

if command -v go >/dev/null 2>&1; then
  go_version=$(go env GOVERSION 2>/dev/null || true)
  go_version=${go_version#go}
  if [ -n "$go_version" ]; then
    major=${go_version%%.*}
    rest=${go_version#*.}
    minor=${rest%%.*}
    if [ "$major" -gt 1 ] || { [ "$major" -eq 1 ] && [ "$minor" -ge 24 ]; }; then
      ok "Go $go_version is >= 1.24"
    else
      fail "Go $go_version is older than 1.24"
    fi
  fi
fi

if command -v helm >/dev/null 2>&1; then
  helm_version=$(helm version --short 2>/dev/null | sed -n 's/^v\([0-9][0-9]*\)\.\([0-9][0-9]*\).*/\1 \2/p')
  if [ -n "$helm_version" ]; then
    set -- $helm_version
    if [ "$1" -gt 3 ] || { [ "$1" -eq 3 ] && [ "$2" -ge 16 ]; }; then
      ok "Helm $1.$2 is >= 3.16"
    else
      fail "Helm $1.$2 is older than 3.16"
    fi
  fi
fi

# ---------------------------------------------------------------------------
# Local values
# ---------------------------------------------------------------------------
echo
echo "Configuration"

valid_domain() {
  [[ $1 =~ ^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)+$ ]]
}
if valid_domain "${zone:-}"; then ok "domain: $zone"; else fail "invalid domain: ${zone:-<empty>}"; fi
if [[ ${admin_email:-} == *@*.* ]]; then ok "admin email: $admin_email"; else fail "invalid admin email: ${admin_email:-<empty>}"; fi
if [[ ${base_dn:-} == dc=* ]]; then ok "base DN: $base_dn"; else fail "base DN does not look like dc=...: ${base_dn:-<empty>}"; fi

read -r -a nodes <<<"${servers:-}"
if [ "${#nodes[@]}" -eq 3 ]; then
  ok "three servers listed"
  if [ "${nodes[0]}" = "${VHOST:-}" ]; then ok "VHOST is the first server"; else fail "VHOST is not the first server"; fi
elif [ "${#nodes[@]}" -eq 0 ]; then
  fail "servers is empty"
else
  fail "expected three servers, found ${#nodes[@]}"
fi

for ip in "${nodes[@]}"; do
  if valid_ip "$ip"; then ok "server address: $ip"; else fail "invalid server address: $ip"; fi
done
if valid_ip "${k3s_control_plane_vip:-}"; then
  ok "VIP: $k3s_control_plane_vip"
  for ip in "${nodes[@]}"; do
    [ "$ip" = "$k3s_control_plane_vip" ] && fail "VIP is also a server address: $ip"
  done
  if command -v ping >/dev/null 2>&1; then
    if ping -c 1 -W 1 "$k3s_control_plane_vip" >/dev/null 2>&1; then
      warn "VIP responds to ping; it may already be in use (okay on a rerun)"
    else
      ok "VIP does not currently respond to ping"
    fi
  fi
else
  fail "invalid VIP: ${k3s_control_plane_vip:-<empty>}"
fi

if valid_cidr "${lab_cidr:-}"; then ok "management CIDR: $lab_cidr"; else warn "invalid management CIDR: ${lab_cidr:-<empty>}"; fi
if valid_cidr "${pod_cidr:-}"; then ok "pod CIDR: $pod_cidr"; else fail "invalid pod CIDR: ${pod_cidr:-<empty>}"; fi
if valid_cidr "${service_cidr:-}"; then ok "service CIDR: $service_cidr"; else fail "invalid service CIDR: ${service_cidr:-<empty>}"; fi
if valid_cidr "${wg_subnet:-}"; then ok "WireGuard subnet: $wg_subnet"; else fail "invalid WireGuard subnet: ${wg_subnet:-<empty>}"; fi
if valid_ip "${wg_server_ip:-}" && ip_in_cidr "${wg_server_ip:-}" "${wg_subnet:-}"; then
  ok "WireGuard gateway address: $wg_server_ip"
else
  fail "WireGuard gateway address is invalid or outside wg_subnet: ${wg_server_ip:-<empty>}"
fi
if valid_port "${wg_port:-}"; then ok "WireGuard port: $wg_port"; else fail "invalid WireGuard port: ${wg_port:-<empty>}"; fi
if [[ ${wg_endpoint:-} == * ]]; then ok "WireGuard endpoint: $wg_endpoint"; else fail "WireGuard endpoint is empty"; fi
if [ -n "${nfs_server:-}" ]; then
  if [[ ${nfs_export:-} == /* ]]; then ok "NFS export: $nfs_export"; else fail "NFS export must be an absolute path: ${nfs_export:-<empty>}"; fi
else
  info "external NFS is not configured; add it later in the console"
fi
if valid_port "${JUMP_PORT:-}"; then ok "JUMP port: $JUMP_PORT"; else fail "invalid JUMP port: ${JUMP_PORT:-<empty>}"; fi
if [ -f "${VSSH_KEY:-}" ]; then ok "SSH key exists: $VSSH_KEY"; else fail "SSH key not found: ${VSSH_KEY:-<empty>}"; fi
case "${longhorn_replica_count:-3}" in
  2|3) ok "Longhorn replicas per volume: ${longhorn_replica_count:-3}" ;;
  *) fail "longhorn_replica_count must be 2 or 3" ;;
esac

# ---------------------------------------------------------------------------
# DNS
# ---------------------------------------------------------------------------
echo
echo "DNS"

resolve_ip() {
  getent ahostsv4 "$1" 2>/dev/null | awk 'NR==1 {print $1}'
}
dns_required=false
if [ "${acme_staging:-}" = false ] && [ "${lab_ca_default:-}" = false ]; then
  dns_required=true
fi
dns_ips=()
dns_missing=false
for host in "auth.${zone:-}" "console.${zone:-}" "lldap.${zone:-}"; do
  [ -n "${zone:-}" ] || break
  ip=$(resolve_ip "$host")
  if [ -z "$ip" ]; then
    if [ "$dns_required" = true ]; then fail "$host does not resolve"; else warn "$host does not resolve (lab CA mode may still work)"; fi
    dns_missing=true
  else
    dns_ips+=("$ip")
  fi
done

if [ "${#dns_ips[@]}" -gt 0 ]; then
  unique_ips=$(printf '%s\n' "${dns_ips[@]}" | sort -u)
  if [ "$(printf '%s\n' "$unique_ips" | wc -l | tr -d ' ')" -ne 1 ]; then
    fail "DNS records resolve to different addresses: $(printf '%s' "$unique_ips" | tr '\n' ' ')"
  else
    resolved=${unique_ips}
    if [ "$resolved" = "${k3s_control_plane_vip:-}" ]; then
      ok "auth/console/lldap -> VIP $resolved"
    elif [ -n "${public_ip:-}" ] && [ "$resolved" = "$public_ip" ]; then
      ok "auth/console/lldap -> public/NAT address $resolved (VIP ${k3s_control_plane_vip:-})"
    elif [ -n "${public_ip:-}" ]; then
      fail "auth/console/lldap -> $resolved (public_ip is ${public_ip}; VIP ${k3s_control_plane_vip:-})"
    else
      ok "auth/console/lldap -> $resolved (dynamic public/NAT address; accepted)"
    fi
  fi
fi
if [ "$dns_missing" = true ] && [ "$dns_required" = true ]; then
  fail "ACME production/staging requires every checked name to resolve"
elif [ "$dns_required" = true ]; then
  ok "ACME production/staging DNS records were checked"
fi

# ---------------------------------------------------------------------------
# SSH / Ansible
# ---------------------------------------------------------------------------
echo
echo "SSH and Ansible"

ssh_opts=(-i "${VSSH_KEY:-/nonexistent}" -p "${JUMP_PORT:-22}" -o BatchMode=yes -o ConnectTimeout=8 -o StrictHostKeyChecking=accept-new)
jump() { ssh "${ssh_opts[@]}" "$JUMP" "$1"; }
node() {
  local host=$1 cmd=$2
  ssh "${ssh_opts[@]}" "$JUMP" "ssh -o BatchMode=yes -o ConnectTimeout=8 -o StrictHostKeyChecking=accept-new ${VUSER:-linux}@${host} '$cmd'"
}

jump_ok=false
if [ -f "${VSSH_KEY:-}" ] && jump 'true' >/dev/null 2>&1; then
  jump_ok=true
  ok "JUMP is reachable: $JUMP"
  if jump 'command -v ansible-playbook >/dev/null 2>&1'; then
    ok "ansible-playbook is installed on JUMP"
    for collection in ansible.posix kubernetes.core; do
      if jump "ansible-galaxy collection list 2>/dev/null | grep -q '$collection'"; then
        ok "Ansible collection: $collection"
      else
        fail "Ansible collection missing on JUMP: $collection"
      fi
    done
  else
    fail "ansible-playbook is not installed on JUMP"
  fi
else
  fail "cannot SSH to JUMP with $VSSH_KEY"
fi

jump_is_target=false
for ip in "${nodes[@]}"; do
  [ "$ip" = "$JUMP" ] && jump_is_target=true
done
if [ "$jump_is_target" = true ]; then
  warn "JUMP is one of the target nodes; a first-run reboot will kill the Ansible process (use a separate host or rerun)"
fi

xt_missing=false
if [ "$jump_ok" = true ]; then
  for ip in "${nodes[@]}"; do
    if ! node "$ip" 'true' >/dev/null 2>&1; then
      fail "cannot SSH from JUMP to ${VUSER:-linux}@$ip"
      continue
    fi
    ok "SSH from JUMP to $ip"
    host=$(node "$ip" 'hostname' 2>/dev/null | tr -d '\r')
    [ -n "$host" ] && ok "hostname $ip: $host"
    if node "$ip" 'sudo -n true' >/dev/null 2>&1; then
      ok "passwordless sudo on $ip"
    else
      fail "passwordless sudo is not available on $ip"
    fi
    os_id=$(node "$ip" 'grep -E ^ID= /etc/os-release 2>/dev/null | cut -d= -f2' 2>/dev/null | tr -d '\r"')
    if [ "$os_id" = rocky ] || [ "$os_id" = rhel ] || [ "$os_id" = centos ]; then
      ok "OS on $ip: $os_id"
    else
      warn "OS on $ip is ${os_id:-unknown}; supported target is Rocky/RHEL"
    fi
    if node "$ip" 'test -e /etc/rancher/k3s/k3s.yaml && echo present || echo absent' 2>/dev/null | grep -q present; then
      warn "k3s state already exists on $ip; this is not a clean first install"
    fi
    if node "$ip" 'lsmod | grep -q ^xt_ && echo xt-ok || echo xt-missing' 2>/dev/null | grep -q xt-missing; then
      xt_missing=true
      warn "kernel on $ip may need the first-run reboot to load xt_* modules"
    fi
  done
fi

# ---------------------------------------------------------------------------
# NFS
# ---------------------------------------------------------------------------
echo
echo "External NFS"

if [ -n "${nfs_server:-}" ]; then
  if [ "$jump_ok" = true ] && [ "${#nodes[@]}" -gt 0 ]; then
    if node "${nodes[0]}" "timeout 3 bash -c \">/dev/tcp/${nfs_server}/2049\"" >/dev/null 2>&1; then
      ok "NFS server $nfs_server accepts TCP/2049"
    else
      fail "cannot reach $nfs_server:2049 from ${nodes[0]}"
    fi
    exports=$(node "${nodes[0]}" "command -v showmount >/dev/null 2>&1 && showmount -e ${nfs_server} 2>/dev/null" 2>/dev/null || true)
    if [ -n "$exports" ]; then
      if printf '%s\n' "$exports" | grep -Fq "$nfs_export"; then
        ok "NFS export is advertised: $nfs_export"
      else
        warn "showmount does not list $nfs_export (NFSv4 pseudo-root may still be valid)"
      fi
    else
      warn "showmount unavailable; cannot confirm that $nfs_export is exported"
    fi
  else
    warn "skipped NFS reachability checks because SSH/JUMP is unavailable"
  fi
  if [ -z "${nfs_export:-}" ]; then fail "nfs_export is empty"; fi
elif [ "${nfs_mode:-}" = external ]; then
  fail "nfs_mode=external but nfs_server is empty"
else
  info "external NFS is not configured; add it later in the console"
fi

# ---------------------------------------------------------------------------
# Summary
# ---------------------------------------------------------------------------
echo
if [ "$fails" -gt 0 ]; then
  echo "PREFLIGHT FAILED: $fails error(s), $warns warning(s)."
  exit 1
fi
if [ "$warns" -gt 0 ]; then
  echo "PREFLIGHT PASSED WITH WARNINGS: $warns warning(s)."
  exit 2
fi
echo "PREFLIGHT PASSED."
exit 0
